"""Offline HTML visual report. Every displayed score comes from evaluation JSON."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from .artifacts import IntegrityError, atomic_write, load_json
from .data import LABELS, SLICES
from .evaluation import assess


def render_report(report: dict[str, Any], data: dict[str, Any], summary: dict[str, Any], output: str | Path) -> None:
    clouds = {}
    for label in LABELS:
        group = next(r["group"] for r in data["records"] if r["label"] == label and r["split"] == "test")
        clouds[label] = {name: next(r["points"] for r in data["records"] if r["group"] == group and r["slice"] == name) for name in SLICES}
    reports = {"healthy": report}
    regression_path = Path(output).parent / "slice-regression.json"
    if regression_path.exists():
        regression = load_json(regression_path)
        if (regression["dataset"]["sha256"] != report["dataset"]["sha256"]
                or regression["models"]["baseline_sha256"] != report["models"]["baseline_sha256"]
                or regression["gate"] != assess(regression["evidence"])):
            raise IntegrityError("Regression report is not consistent with the displayed evaluation")
        reports["regression"] = regression
    payload = json.dumps({"reports": reports, "clouds": clouds, "summary": summary}, allow_nan=False).replace("<", "\\u003c")
    html = HTML.replace("__PAYLOAD__", payload)
    atomic_write(output, html.encode())


