 el('policyVersion').textContent='Policy '+R.policy.version+' · '+R.gate.decision;el('policyVersion').classList.toggle('recall-highlight',blocked);
 el('hashes').textContent='DATASET '+R.dataset.sha256+'\nCANDIDATE '+R.models.candidate_sha256;el('hashes').style.whiteSpace='pre-wrap';
